def check_quality(path_pattern: str, min_score: int = 80) -> dict:
    """检查代码质量"""
    # 直接使用 glob，不需要修改路径
    files = glob.glob(path_pattern, recursive=True)

    if not files:
        return {
            'success': False,
            'message': f'No files found matching: {path_pattern}',
            'files_checked': 0,
            'average_score': 0,
            'min_required': min_score,
            'passed': False
        }

