def run_pylint(file_path: str) -> dict:
    """运行 pylint 检查"""
    try:
        result = subprocess.run(
            ['pylint', '--output-format=json', file_path],
            capture_output=True,
            text=True,
            encoding='utf-8',
            timeout=30
        )

        if result.returncode == 0 or result.stdout:
            try:
                issues = json.loads(result.stdout) if result.stdout else []
            except:
                issues = []

            # 计算分数
            score = 10.0
            for issue in issues:
                if isinstance(issue, dict):
                    msg_type = issue.get('type', '')
                    if msg_type == 'error':
                        score -= 2.0
                    elif msg_type == 'warning':
                        score -= 1.0
                    elif msg_type == 'convention':
                        score -= 0.5

            return {
                'success': True,
                'score': max(0, score * 10),  # 转换为 0-100
                'issues': len(issues),
                'file': file_path
            }
    except Exception as ex:
        pass

    return {
        'success': False,
        'score': 0,
        'issues': 0,
        'file': file_path,
        'error': str(ex) if 'ex' in locals() else 'Unknown error'
    }

