def run_pylint(file_path: str) -> dict:
    """运行代码质量检查（使用 flake8 或简单语法检查）"""
    try:
        # 尝试使用 flake8
        result = subprocess.run(
            ['flake8', '--count', file_path],
            capture_output=True,
            text=True,
            encoding='utf-8',
            timeout=30
        )

        # flake8 返回 1 表示有问题，但不一定是错误
        error_count = 0
        warning_count = 0

        if result.stdout:
            lines = result.stdout.strip().split('\n')
            for line in lines:
                if line and not line.endswith('errors'):
                    error_count += 1

        # 计算分数 (每 10 个错误扣 1 分)
        score = max(0, 100 - (error_count * 2))

        return {
            'success': True,
            'score': score,
            'issues': error_count,
            'file': file_path
        }
    except Exception as ex:
        # flake8 不可用时，进行简单语法检查
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                compile(f.read(), file_path, 'exec')
            return {
                'success': True,
                'score': 100,
                'issues': 0,
                'file': file_path
            }
        except SyntaxError:
            return {
                'success': False,
                'score': 0,
                'issues': 1,
                'file': file_path,
                'error': 'Syntax error'
            }
        except Exception as ex2:
            return {
                'success': False,
                'score': 0,
                'issues': 1,
                'file': file_path,
                'error': str(ex2)
            }

