def scan_new_tools() -> list:
    """扫描新创建的工具"""
    scripts_dir = Path('30-scripts-tools')
    registry_file = scripts_dir / 'tools_registry.json'

    # 获取已注册的工具
    registered_tools = set()
    if registry_file.exists():
        with open(registry_file, 'r', encoding='utf-8') as f:
            registry = json.load(f)
            for tool_id in registry.get('tools', {}).keys():
                registered_tools.add(tool_id)

    # 扫描新的 Python 文件
    new_tools = []
    for py_file in scripts_dir.glob('*.py'):
        if py_file.name in ['tool_executor.py', 'session_end.py', 'post_session_compress.py']:
            continue  # 跳过核心脚本

        tool_name = py_file.stem.replace('_', '-')
        if tool_name not in registered_tools:
            # 检查是否是工具文件（有 main 函数）
            content = py_file.read_text(encoding='utf-8', errors='replace')
            if 'def main()' in content or 'argparse' in content:
                new_tools.append({
                    'file': str(py_file),
                    'tool_name': tool_name,
                    'registered': False
                })

    return new_tools
